package com.bankapp;
import javax.swing.*;import javax.swing.border.*;import javax.imageio.ImageIO;import java.awt.*;import java.util.Arrays;
/** Full-screen branded staff login. Demo credentials only; not production authentication. */
public class LoginFrame extends JFrame {
 private final JTextField username=new JTextField("staff",20);private final JPasswordField password=new JPasswordField(20);private int attempts=0;
 public LoginFrame(Runnable onSuccess){super("Aureum Bank | Secure Staff Login");setDefaultCloseOperation(EXIT_ON_CLOSE);setExtendedState(JFrame.MAXIMIZED_BOTH);setMinimumSize(new Dimension(900,600));
 JPanel backdrop=new JPanel(new GridBagLayout()){protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D q=(Graphics2D)g.create();q.setPaint(new GradientPaint(0,0,new Color(4,5,8),getWidth(),getHeight(),new Color(49,37,17)));q.fillRect(0,0,getWidth(),getHeight());q.setColor(new Color(232,180,53,28));for(int i=0;i<7;i++)q.drawOval(getWidth()-530+i*38,-160+i*32,600,600);q.dispose();}};setContentPane(backdrop);
 JPanel card=new JPanel();card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.setBackground(Theme.PANEL);card.setBorder(new CompoundBorder(BorderFactory.createLineBorder(new Color(109,84,37),2,true),BorderFactory.createEmptyBorder(32,65,38,65)));card.setPreferredSize(new Dimension(470,570));
 JLabel emblem=new JLabel();try{java.net.URL u=getClass().getResource("/com/bankapp/bank-logo.png");if(u!=null)emblem.setIcon(new ImageIcon(ImageIO.read(u).getScaledInstance(145,145,Image.SCALE_SMOOTH)));}catch(Exception ignored){}emblem.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(emblem);card.add(Box.createVerticalStrut(10));JLabel title=new JLabel("AUREUM BANK");title.setFont(new Font("SansSerif",Font.BOLD,29));title.setForeground(Theme.GOLD);title.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(title);JLabel subtitle=new JLabel("STAFF ACCESS  /  PRIVATE BANKING");subtitle.setFont(new Font("SansSerif",Font.PLAIN,11));subtitle.setForeground(new Color(185,179,160));subtitle.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(Box.createVerticalStrut(7));card.add(subtitle);card.add(Box.createVerticalStrut(32));
 for(JTextField field:new JTextField[]{username,password}){field.setMaximumSize(new Dimension(330,45));field.setPreferredSize(new Dimension(330,45));field.setBackground(new Color(37,38,43));field.setForeground(Color.WHITE);field.setCaretColor(Theme.GOLD);field.setFont(new Font("SansSerif",Font.PLAIN,15));field.setBorder(new CompoundBorder(BorderFactory.createLineBorder(new Color(123,94,40)),BorderFactory.createEmptyBorder(8,12,8,12)));}
 addLabel(card,"USERNAME");card.add(username);card.add(Box.createVerticalStrut(17));addLabel(card,"PASSWORD");card.add(password);card.add(Box.createVerticalStrut(28));JButton login=new JButton("SIGN IN  →");Theme.button(login);login.setMaximumSize(new Dimension(330,50));login.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(login);login.addActionListener(e->{char[] pw=password.getPassword();boolean valid="staff".equals(username.getText().trim())&&Arrays.equals(pw,"Demo@123".toCharArray());Arrays.fill(pw,'\0');password.setText("");if(valid){dispose();onSuccess.run();}else{attempts++;JOptionPane.showMessageDialog(this,"Incorrect username or password.","ACCESS DENIED",JOptionPane.ERROR_MESSAGE);if(attempts>=3)dispose();}});password.addActionListener(e->login.doClick());backdrop.add(card);}
 private static void addLabel(JPanel p,String text){JLabel l=new JLabel(text);l.setForeground(Theme.GOLD);l.setFont(new Font("SansSerif",Font.BOLD,12));l.setAlignmentX(Component.CENTER_ALIGNMENT);p.add(l);p.add(Box.createVerticalStrut(7));}
}
